using System;
using System.Collections.Immutable;
using System.Text;
using BGCS.Core.Common;
using BGCS.Core.Inputs;

namespace BGCS.Core.Artifacts;

/// <summary>Identifies a generated file's actual parse, compilation or packaging role.</summary>
public enum SourceContributionRole
{
    /// <summary>A generated native header available to declared parse and build inputs.</summary>
    PublicHeader,
    /// <summary>A generated native compilation unit with an explicit source language.</summary>
    NativeSource,
    /// <summary>An additional managed source validated with the emitted API.</summary>
    ManagedSource,
    /// <summary>An auxiliary text or binary resource; it is not an inferred compilation unit.</summary>
    Resource
}

/// <summary>Owns generated bytes relative to one service's role root; the Host validates and copies them before staging.</summary>
/// <param name="relativePath">The portable relative path within the service-owned role namespace.</param>
/// <param name="role">The explicit source or resource role.</param>
/// <param name="mediaType">The declared content media identity, validated against source role and language.</param>
/// <param name="content">Complete immutable content bytes, not a path to ambient generated output.</param>
public sealed record SourceContributionArtifact(
    string relativePath,
    SourceContributionRole role,
    string mediaType,
    ImmutableArray<byte> content
)
{
    /// <summary>Gets C or Cpp for native source/header content; None for managed source and resources.</summary>
    public SourceLanguage language { get; init; }
    /// <summary>Gets whether a public header supplies original binding entry declarations.</summary>
    public bool exposeToBindings { get; init; }

    /// <summary>Strictly encodes text into a new immutable UTF-8 byte collection without replacing invalid surrogates.</summary>
    /// <param name="relativePath">The portable relative path within the service-owned role namespace.</param>
    /// <param name="role">The explicit source or resource role.</param>
    /// <param name="mediaType">The declared content media identity.</param>
    /// <param name="text">The complete source or resource text.</param>
    /// <param name="language">The explicit native language, or None for managed sources and resources.</param>
    /// <param name="exposeToBindings">Whether this public header enters original binding selection.</param>
    /// <returns>A new immutable source artifact; path and role validation remain Host responsibilities.</returns>
    /// <exception cref="ArgumentNullException">The source text is null.</exception>
    /// <exception cref="EncoderFallbackException">The source text contains an invalid surrogate sequence.</exception>
    public static SourceContributionArtifact FromUtf8(
        string relativePath,
        SourceContributionRole role,
        string mediaType,
        string text,
        SourceLanguage language = SourceLanguage.None,
        bool exposeToBindings = false
    ) {
        ArgumentNullException.ThrowIfNull(text);
        return new(relativePath, role, mediaType, ImmutableArray.CreateRange(new UTF8Encoding(false, true).GetBytes(text)))
        { language = language, exposeToBindings = exposeToBindings };
    }
}

/// <summary>Freezes all generated files together; native verification is established by later independent gates.</summary>
/// <param name="artifacts">The complete native, managed and resource contribution for one target.</param>
/// <param name="evidence">Declared or user-asserted provenance, validated by the Host without an automatic Verified upgrade.</param>
public sealed record SourceContribution(
    ImmutableArray<SourceContributionArtifact> artifacts,
    Evidence evidence
);
